import assert from 'node:assert/strict';import {permit} from './limit.mjs';
const cases=[[0,true],[1,true],[2,true],[3,true],[-0,true],[-1,false],[4,false],[5,false],[1.5,false],[NaN,false],[Infinity,false],[-Infinity,false],['3',false],[null,false],[undefined,false],[true,false],[false,false],[{},false],[[],false],[Number.MAX_SAFE_INTEGER+1,false]];
for(const [v,expected] of cases)assert.equal(permit(v),expected,String(v));console.log(JSON.stringify({cases:cases.length,passed:cases.length}));
